            foreach ($name in $script:sameAttributes) {
                $own = @($shim.Test.$name | Where-Object { $null -ne $_ -and "$_" -ne '' }) -join ', '
                $theirs = @($shim.Target.$name | Where-Object { $null -ne $_ -and "$_" -ne '' }) -join ', '
